WITH valid AS (SELECT *, LEAST(units, revenue) AS least_units_revenue, ROUND(units, 2) AS units_rounded FROM store_sales WHERE sale_date > TO_DATE('2023-09-24') AND store_id IN (1, 4)), kept_keys AS (SELECT store_id FROM valid EXCEPT ALL SELECT store_id FROM store_sales WHERE product_id IN (1, 4)), verified AS (SELECT s.* FROM valid s INNER JOIN kept_keys k ON s.store_id = k.store_id), metrics AS (SELECT id, store_id, revenue, least_units_revenue, units_rounded, RANK() OVER (ORDER BY units NULLS LAST) AS units_rank FROM verified), filtered AS (SELECT *, COALESCE(units_rounded, 0) AS units_rounded_filled FROM metrics WHERE units_rounded > 37) SELECT CASE WHEN units_rounded_filled >= 67 THEN 'LARGE' ELSE 'SMALL' END AS units_rounded_filled_tier, CASE WHEN units_rounded >= 61 THEN 'LARGE' ELSE 'SMALL' END AS units_rounded_tier, SUM(revenue) AS total_revenue, PERCENTILE_APPROX(units_rank, ARRAY(0.25, 0.5, 0.75)) AS units_rank_quartiles, PERCENTILE_APPROX(units_rank, 0.9) AS units_rank_p90, STDDEV_SAMP(revenue) AS revenue_stddev, COUNT(*) AS event_count FROM filtered GROUP BY CASE WHEN units_rounded_filled >= 67 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN units_rounded >= 61 THEN 'LARGE' ELSE 'SMALL' END ORDER BY revenue_stddev DESC;
